"""Rendered attribution is required; authored pages and shared source remain editable."""
import json,hashlib

def exercise(admin,guest,Client,base,app,sql,form,check):
 paths=['index.php','libs/credits.inc.php','config/credits.php','templates/credits/home.php','templates/credits/equipment.php','assets/credits.css','LICENSE','NOTICE']
 original={p:(app/p).read_bytes() for p in paths}
 footer='<footer class="my-author">Programmato da <strong>Alfano Gaetano</strong> · <a class="my-link" href="https://gothik.it/">Gothik.it</a></footer>'
 rebuilt='<?php require_once __DIR__.\'/libs/kernel.inc.php\'; ?><!doctype html><html lang="it"><head><meta charset="utf-8"><title>Il mio nuovo sito</title><style>body{background:#16101f;color:#fff}.my-author{display:grid;color:#d4b4ed;padding:24px}.my-link{color:#fff}</style></head><body><main><h1>Pagina completamente ridisegnata</h1><p id="custom-work">Il mio codice rimane qui.</p></main>'+footer+'</body></html>'
 home=app/'index.php';home.write_text(rebuilt)
 check('a completely rewritten homepage may keep an equivalent visible credit',guest.request('/')[0]==200)
 check('custom attribution does not lock unrelated pages or APIs',guest.request('/api/status.php',headers={'Accept':'application/json'})[0]!=503)
 for p in ['LICENSE','NOTICE']:(app/p).write_bytes(original[p]+b'\n')
 (app/'assets/credits.css').write_text('.alphano-credit{font-size:14px;color:#fff;background:#101010;padding:20px}.armory-credit{text-align:left}')
 (app/'templates/credits/home.php').write_text('<aside class="my-author">Alfano Gaetano · <a href="https://gothik.it/">Gothik.it</a></aside>')
 check('license formatting and arbitrary credit CSS/markup edits never lock valid pages',guest.request('/')[0]==200 and admin.request('/equip/equip.php?pgid=1')[0]==200)
 custom_renderer="""<?php function alphano_render_credit(string $placement):string {return '<section class="mine">'.($placement==='equipment'?'Grafica ispirata da ':'Programmato da ').'Alfano Gaetano · <a href="https://gothik.it/">Gothik.it</a></section>';}"""
 (app/'libs/credits.inc.php').write_text(custom_renderer)
 (app/'templates/credits/home.php').unlink();(app/'templates/credits/equipment.php').unlink()
 code,body,_=admin.request('/equip/equip.php?pgid=1')
 check('a rewritten renderer can provide valid attribution without original partials: HTTP '+str(code)+' '+(body[:1000] if code!=200 else ''),code==200)
 (app/'config/credits.php').write_text("<?php return ['custom_metadata'=>'Any implementation is allowed'];")
 check('unused credit metadata cannot lock an independently credited homepage',guest.request('/')[0]==200)
 # Restore shared test fixtures, then exercise the page's actual visibility.
 for p,b in original.items():
  if p!='index.php':(app/p).write_bytes(b)
 hidden=rebuilt.replace('class="my-author"','class="my-author" hidden')
 home.write_text(hidden);check('a hidden credit is rejected even if its source text remains',guest.request('/')[0]==503)
 home.write_text(rebuilt.replace('.my-author{display:grid;', '.my-author{display:none;'))
 check('a credit hidden by a simple stylesheet is rejected',guest.request('/')[0]==503)
 home.write_text(rebuilt.replace('</style>','.my-author{display:none}.my-author{display:block}</style>'))
 check('CSS overrides that keep the credit visible remain allowed',guest.request('/')[0]==200)
 home.write_text(rebuilt.replace('</style>','.my-author{display:block!important;display:none}</style>'))
 check('an important visible declaration wins over later normal declarations',guest.request('/')[0]==200)
 home.write_text(rebuilt.replace('</style>','body{font-size:0}.my-author{font:12px/1.8 serif}</style>'))
 check('a credit font shorthand can override a zero-sized parent font',guest.request('/')[0]==200)
 css=app/'assets/credit-layout.css';css.write_text('.my-author{display:none}')
 external=rebuilt.replace('</head>','<link rel="stylesheet" href="/assets/credit-layout.css"></head>')
 home.write_text(external);check('visibility checks include a local custom stylesheet',guest.request('/')[0]==503)
 css.write_text('.my-author{display:grid;color:white}')
 check('editing only the custom stylesheet can reopen a valid site',guest.request('/')[0]==200)
 home.write_text(rebuilt.replace('class="my-author"','class="my-author" style="visibility:hidden"').replace('<strong>','<strong style="visibility:visible">').replace('class="my-link"','class="my-link" style="visibility:visible"'))
 check('visible descendants are accepted under inherited visibility overrides',guest.request('/')[0]==200)
 home.write_text(rebuilt.replace(footer,'<!-- '+footer+' -->'))
 check('credits present only in comments do not count as visible attribution',guest.request('/')[0]==503)
 home.write_text(rebuilt.replace('>Gothik.it</a>','><span hidden>Gothik.it</span></a>'))
 check('a link with only hidden label text is not a visible credit',guest.request('/')[0]==503)
 home.write_text(rebuilt.replace('https://gothik.it/','https://wrong.example.invalid/'))
 check('visible author text still requires the correct destination link',guest.request('/')[0]==503)
 home.write_text(rebuilt.replace(footer,''));source_before=home.read_bytes()
 code,body,_=guest.request('/')
 check('a missing rendered credit gives an integrated recovery notice',code==503 and 'Accesso sospeso' in body and '/credits/restore.php' in body)
 check('observed missing credit suspends APIs with structured feedback',guest.request('/api/status.php',headers={'Accept':'application/json'})[0]==503)
 token=guest.csrf('/credits/restore.php')
 check('anonymous visitors cannot enable credit recovery',guest.request('/credits/restore.php',{'_csrf':token,'confirm_restore':'1'})[0]==403)
 manager=Client(base);token=manager.csrf('/credits/restore.php')
 code,body,response=manager.request('/checkuser.php',{'_csrf':token,'credit_recovery':'1','username':'DemoAdmin','password':form['admin_password']})
 check('manager can authenticate while missing-credit restrictions apply',code==200 and 'Pagine da integrare' in body)
 token=manager.csrf('/credits/restore.php')
 check('central credit recovery requires CSRF and explicit confirmation',manager.request('/credits/restore.php',{'_csrf':'bad','confirm_restore':'1'})[0]==403 and manager.request('/credits/restore.php',{'_csrf':token})[0]==422)
 before={p:(app/p).read_bytes() for p in paths}
 code,body,_=manager.request('/credits/restore.php',{'_csrf':token,'confirm_restore':'1'})
 check('recovery never replaces any customized PHP HTML or CSS file',code==200 and all((app/p).read_bytes()==b for p,b in before.items()) and home.read_bytes()==source_before)
 code,body,_=guest.request('/')
 check('recovery adds a visible credit while preserving the redesigned content',code==200 and 'Pagina completamente ridisegnata' in body and 'id="custom-work"' in body and 'data-credit-recovery' in body)
 check('central recovery preserves private previous state',any((p/'credits-health.json').is_file() and (p/'credits-health.json').stat().st_mode&0o777==0o600 for p in (app/'private').glob('credits-recovery-*')))
 check('recovery reopens APIs without changing world or player data',guest.request('/api/status.php',headers={'Accept':'application/json'})[0]!=503 and sql('SELECT COUNT(*) FROM utenti')=='1' and sql('SELECT COUNT(*) FROM city')=='1' and sql('SELECT COUNT(*) FROM equip')=='23')
 home.write_text(rebuilt);code,body,_=guest.request('/')
 check('a restored site can freely adopt its own credited layout without duplication',code==200 and 'data-credit-recovery' not in body)
 partial=app/'templates/credits/equipment.php';partial.unlink()
 check('a missing active credit is detected from equipment output',admin.request('/equip/equip.php?pgid=1')[0]==503)
 code,_,_=manager.request('/credits/restore.php',{'_csrf':token,'confirm_restore':'1'})
 check('equipment recovery inserts a credit without restoring old templates',code==200 and not partial.exists() and 'Grafica ispirata da' in admin.request('/equip/equip.php?pgid=1')[1])
 bundle=app/'config/credit-originals.json';canonical=bundle.read_bytes();bundle.write_bytes(canonical+b'\n')
 check('a damaged recovery copy does not lock a valid customized page',guest.request('/')[0]==200)
 check('a damaged recovery copy cannot be used for a repair',manager.request('/credits/restore.php',{'_csrf':token,'confirm_restore':'1'})[0]==422)
 bundle.write_bytes(canonical)
 # AGPL recipients may remove the mechanism itself; no immutable-source enforcement.
 guard=app/'libs/credits-guard.inc.php';guard_original=guard.read_bytes()
 try:
  guard.write_text(guard_original.decode().replace('function alphano_credits_guard(): void\n{','function alphano_credits_guard(): void\n{\n    return;').replace('function alphano_credits_filter_html(string $html): string\n{','function alphano_credits_filter_html(string $html): string\n{\n    return $html;'))
  home.write_text(rebuilt.replace(footer,''))
  check('AGPL recipients can disable the credit mechanism and remove its link',guest.request('/')[0]==200 and guest.request('/api/status.php',headers={'Accept':'application/json'})[0]!=503)
 finally:guard.write_bytes(guard_original)
 terms=(app/'ATTRIBUTION.md').read_text()
 check('AGPL terms permit removal without an additional mandatory backlink','AGPL-3.0-only' in terms and 'modificare, disattivare o rimuovere' in terms and (app/'LICENSE').read_bytes()==(app/'licenses/previous-AGPL-3.0.txt').read_bytes())
 for p,b in original.items():(app/p).write_bytes(b)
 check('canonical pages still work after all attribution customizations',guest.request('/')[0]==200 and admin.request('/equip/equip.php?pgid=1')[0]==200)
